import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { Button, Form, Modal } from 'antd'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import CircularLoader from '../../../../../../../components/CircularLoader/index'
import { showNotification } from '../../../../../../../components/ShowNotification'
import Accessories from '../../../../components/Accessories'
import Addons from '../../../../components/Addons'
import { OFFLINE_LANG } from '../../../../OfflineQuotes/lang'
import { useGetPolicyDetails, usePolicyEditItemData, usePolicyEditItemList, useValidatePolicyData } from '../../../state/hooks/useAgentPolicyState'
import { getAddonsMapBody, getEditPolicyBodyReq } from '../../../utility'
import PolicyForm from '../components/PolicyForm'
import { PolicyEditStyle } from './index.style'

function PolicyEditContainer ({ match, form, history }) {
  const policyId = useMemo(() => {
    const urlParams = match?.params
    return urlParams.policyId
  }, [match])
  const [{ getPolicyDetailsData }, getPolicyDetailReq] = useGetPolicyDetails()
  const [{ GET_POLICY_EDITABLE_ITEMS_LIST_LOADER, POLICY_EDITABLE_ITEMS_DATA_LOADER }] = useLoaderContextValue()
  const [{ getPolicyEditableItemsListData }, getPolicyItemListReq] = usePolicyEditItemList()
  const [{ validatePolicyData }, validatePolicyReq] = useValidatePolicyData()
  const [, submitEditPolicyFormReq] = usePolicyEditItemData()
  const [errorState] = useErrorContextValue()
  const { resetError } = useResetError()
  const that = useRef({
    isPolicyDocumentEdit: !!match?.params?.document
  })

  const chassisRef = useRef({
    clearChassisTimeOut: '',
    tempChassisNumber: ''
  })
  const [isReviewDisabled, setIsReviewDisabled] = useState(true)
  const [showReview, setShowReview] = useState(false)
  useEffect(() => {
    getPolicyDetailReq({
      policyId
    })
    getPolicyItemListReq({
      policyId
    })
  }, [getPolicyItemListReq, getPolicyDetailReq, policyId])

  const handleSave = useCallback((isValid) => {
    // handle save details
    const bodyMap = {}
    if (that.current.accessories) {
      bodyMap.accessories = that.current.accessories
    }
    if (that.current.addons) {
      bodyMap.add_ons = that.current.addons
    }
    if (that.current.insurance_policy_data) {
      bodyMap.insurance_policy_data = that.current.insurance_policy_data
    }
    if (that.current.extra_documents) {
      bodyMap.extra_documents = that.current.extra_documents.filter((item) => {
        return item.url
      })
      if (!bodyMap.extra_documents.length) {
        bodyMap.extra_documents = []
      }
    }
    if (that.current.premium_note_urls) {
      bodyMap.premium_note_urls = that.current.premium_note_urls
    }
    const formData = form.getFieldsValue()
    bodyMap.province_name = document.getElementById('province_code')?.innerText
    bodyMap.city_name = document.getElementById('city_code')?.innerText
    if (isValid) {
      const data = getEditPolicyBodyReq({
        ...formData,
        ...bodyMap
      },
      getPolicyEditableItemsListData
      )
      submitEditPolicyFormReq({
        body: {
          data
        },
        policyId
      })
    }
  }, [submitEditPolicyFormReq, policyId, form, getPolicyEditableItemsListData])

  const handleEditDetails = useCallback(() => {
    let isValid = false
    form.validateFields((err, values) => {
      if (err) {
        return
      }
      isValid = true
    })
    let content = 'I understand that the data changes I made are not part of the endorsement or do not cause changes to the premium calculation.'
    if (that.current.isPolicyDocumentEdit) {
      content = 'Are you sure to update the document?'
    }
    if (isValid) {
      Modal.confirm({
        content,
        onOk: () => handleSave(isValid),
        okText: 'Yes',
        cancelText: 'No'
      })
    }
  }, [handleSave, form])

  const handleSaveConfirmation = useCallback(() => {
    const { request: { code, start_date: policyStartDate } } = getPolicyDetailsData
    const { vehicle_chasis_number: chassisNumber } = form.getFieldsValue()
    if (chassisNumber !== chassisRef.current.tempChassisNumber) {
      clearTimeout(chassisRef.current.clearChassisTimeOut)
    }

    chassisRef.current.tempChassisNumber = chassisNumber

    if (chassisNumber) {
      validatePolicyReq({
        code,
        identifier_value: policyId,
        identifier: 'reference_id',
        pre_validate_data: {
          chasis_number: {
            chasis_number: chassisNumber,
            start_date: policyStartDate
          }
        }
      })
    } else {
      handleEditDetails()
    }
  }, [getPolicyDetailsData, handleEditDetails, validatePolicyReq, policyId, form])

  useEffect(() => {
    const {
      policyEditableItemsDataStatus, policyEditableItemsDataErrorData,
      validatePolicyStatus
    } = errorState
    if (policyEditableItemsDataStatus === 'success') {
      showNotification('success', 'Successfully updated the policy data')
      history.goBack()
      resetError(['policyEditableItemsDataStatus'])
    } else if (policyEditableItemsDataStatus) {
      showNotification('error', policyEditableItemsDataErrorData.message)
      resetError(['policyEditableItemsDataStatus'])
    } else if (validatePolicyStatus === 'success') {
      const { success } = validatePolicyData
      if (success) {
        handleEditDetails()
      } else if (validatePolicyData.is_request_pending) {
        chassisRef.current.clearChassisTimeOut = setTimeout(() => {
          handleSaveConfirmation()
        }, 20000)
      } else {
        showNotification('error', OFFLINE_LANG.applicationStatusAfterChassisValidation)
      }
      resetError(['validatePolicyStatus'])
    }
  }, [
    errorState, validatePolicyData, history,
    handleSaveConfirmation, handleEditDetails, resetError
  ])

  const handleSavePolicyData = useCallback((data) => {
    that.current = data
  }, [])

  const handleSaveAddonsData = useCallback(data => {
    that.current.addons = {
      ...getAddonsMapBody(data),
      addons: [
        ...data
      ]
    }
  }, [])

  const handleEditDocumentChange = useCallback((data, type) => {
    that.current[type] = data
    setIsReviewDisabled(false)
  }, [])

  const handleCustomerInfoChange = useCallback((data, type) => {
    that.current[type] = data
  }, [])

  const renderForm = useCallback(() => {
    const mapArr = []
    for (const key in getPolicyEditableItemsListData) {
      // map the content data
      const data = getPolicyEditableItemsListData[key]
      switch (key) {
        case 'Customer Information':
          mapArr.push(
            <PolicyForm
              key={key}
              title={key}
              customerInfoForm={data}
              form={form}
              policyId={policyId}
              onChange={handleCustomerInfoChange}
            />
          )
          break
        case 'Edit Policy Number & Documents':
          mapArr.push(
            <PolicyForm
              key={key}
              title={key}
              customerInfoForm={data}
              form={form}
              colSpan={24}
              policyId={policyId}
              showReview={showReview}
              onChange={handleEditDocumentChange}
            />
          )
          break
        case 'Additional Accessories': {
          mapArr.push(
            <Accessories
              key={key}
              defaultAccessories={data[0]?.default_value || []}
              isEdit
              isDelete
              onSaveAccessory={handleSavePolicyData}
            />
          )
          break
        }
        case 'Addons': {
          mapArr.push(
            <Addons
              key={key}
              title={key}
              policy={getPolicyDetailsData}
              defaultAddons={data[0]?.default_value || []}
              onSaveAddonsData={handleSaveAddonsData}
            />
          )
          break
        }
        case 'Others': {
          mapArr.push(
            <PolicyForm
              key={key}
              title={key}
              customerInfoForm={data}
              form={form}
              policyId={policyId}
            />
          )
          break
        }
        default:
          break
      }
    }
    return mapArr
  }, [
    getPolicyEditableItemsListData, showReview, handleSavePolicyData,
    form, policyId, getPolicyDetailsData, handleSaveAddonsData,
    handleEditDocumentChange, handleCustomerInfoChange
  ])

  const handleSaveReview = useCallback((data) => {
    // handle the review
    let isValid = false
    form.validateFields((err, values) => {
      if (err) {
        return
      }
      isValid = true
    })
    if (isValid) {
      setShowReview(true)
    }
  }, [form])

  const handleBack = () => {
    if (showReview) {
      setShowReview(false)
      return
    }
    history.goBack()
  }

  return (
    <CircularLoader isSpining={GET_POLICY_EDITABLE_ITEMS_LIST_LOADER || POLICY_EDITABLE_ITEMS_DATA_LOADER}>
      <PolicyEditStyle>
        <h3>Policy Edit</h3>
        <Form noValidate>
          {
            getPolicyEditableItemsListData && getPolicyDetailsData?.app_no && renderForm()
          }
        </Form>
        <div className='action-container'>
          {
            (that.current.isPolicyDocumentEdit && !showReview) && (
              <Button
                type='primary'
                className='action-save'
                onClick={handleSaveReview}
                disabled={isReviewDisabled}
              >
                Review
              </Button>
            )
          }
          {
            ((that.current.isPolicyDocumentEdit && showReview) || !that.current.isPolicyDocumentEdit) && (
              <Button
                type='primary'
                className='action-save'
                onClick={handleSaveConfirmation}
              >
                Save
              </Button>
            )
          }
          <Button onClick={handleBack}>Back</Button>
        </div>
      </PolicyEditStyle>
    </CircularLoader>
  )
}

export default Form.create()(PolicyEditContainer)
