export const getIsQuoteAccepted = (quoteStatus) => {
  if ([QUOTE_IN_PROGRESS, QUOTE_ISSUED].includes(quoteStatus)) {
    return {
      text: QUOTE_STATUS_LANG[quoteStatus],
      color: COLORS.orange
    }
  } else if ([ACCEPTED, CLOSING_SLIP_GENERATED, POLICY_ISSUED].includes(quoteStatus)) {
    return {
      text: QUOTE_STATUS_LANG[quoteStatus],
      color: COLORS.green
    }
  }
}

