import { Form, Input, Modal, Radio, Row, Col, Button, Icon } from 'antd'
import { useCallback, useEffect, useRef, useState } from 'react'
import { InputNumberStyle } from '../../components/AddressChanges/container/index.style'
import UploadImgPreview from '../UploadIgPreview'
import { AddonModalStyle } from './index.style'

function EditAccessoryModal ({ show, onClose, form, accessory, editIndex, isAddNew, onSave = () => {} }) {
  const accessoryKey = useRef(isAddNew ? 0 : 1)
  const [newAccessories, setNewAccessories] = useState((() => {
    if (Object.keys(accessory).length) {
      return [
        {
          ...accessory,
          accessoryKey: accessoryKey.current
        }
      ]
    }
    return [{
      accessoryKey: accessoryKey.current
    }]
  })())

  const isPhotoSet = useRef(false)

  useEffect(() => {
    if (!isPhotoSet.current && accessory.img) {
      isPhotoSet.current = true
      form.setFieldsValue({
        [`accessory_photo${accessoryKey.current}`]: accessory.img
      })
    }
  }, [accessory, form])

  const handleFormSubmit = useCallback(() => {
    form.validateFields((err, values) => {
      if (err) {
        return
      }
      const mappedAccessories = newAccessories.map(item => {
        const key = item.accessoryKey
        return {
          accessory_type: values[`accessory_type${key}`],
          name: values[`name${key}`],
          sum_insured: values[`sum_insured${key}`],
          img: values[`accessory_photo${key}`]
        }
      })
      onSave(mappedAccessories, editIndex)
    })
  }, [form, onSave, editIndex, newAccessories])

  const getFormFieldsDecorator = useCallback(({ name, title, error, defaultValue }, renderElement) => {
    return (
      <Form.Item label={title}>
        {
          form.getFieldDecorator(
            name,
            {
              rules: [
                {
                  required: true,
                  message: error || `Please enter ${title}`
                }
              ],
              initialValue: defaultValue
            }
          )(renderElement)
        }
      </Form.Item>
    )
  }, [form])

  const handleUploadFile = useCallback((data, index, keyValue) => {
    setNewAccessories(oldAccessory => {
      oldAccessory[index].img = data
      return [
        ...oldAccessory
      ]
    })
    form.setFieldsValue({
      [keyValue]: data
    })
  }, [form])

  const handleRemoveAccessory = useCallback((index) => {
    setNewAccessories(prevAccessories => {
      prevAccessories.splice(index, 1)
      return [...prevAccessories]
    })
  }, [])

  const renderAccessoryFormItem = useCallback((accessory, index) => {
    return (
      <Row type='flex' key={`accessories-${accessory.accessoryKey}`} className='accessory-container'>
        {
          !!index && <Icon onClick={() => handleRemoveAccessory(index)} type='close-circle' className='accessory-close-icon' />
        }
        <Col sm={8} md={8}>
          <Form.Item label='Accessory Photo'>
            {
              form.getFieldDecorator(
                `accessory_photo${accessory.accessoryKey}`,
                {
                  rules: [
                    {
                      required: true,
                      message: 'Please Enter the Accessory Photo'
                    }
                  ],
                  value: accessory.img
                }
              )(
                <UploadImgPreview
                  onSave={(file) => handleUploadFile(file, index, `accessory_photo${accessory.accessoryKey}`)}
                  name={`accessory_photo${accessory.accessoryKey}`}
                  title='Accessory Photo'
                  img={accessory.img}
                  fileType='.png,.jpg,.jpeg'
                />
              )
            }
          </Form.Item>
        </Col>
        <Col xl={16} md={16}>
          {
            getFormFieldsDecorator(
              {
                name: `accessory_type${accessory.accessoryKey}`,
                title: 'Accessory Type',
                defaultValue: accessory.accessory_type,
                error: 'Please Enter the Accessory Type'
              },
              (
                <Radio.Group>
                  <Radio value='standard'>Standar</Radio>
                  <Radio value='non-standard'>Non Standar</Radio>
                </Radio.Group>
              )
            )
          }
          {
            getFormFieldsDecorator(
              {
                name: `name${accessory.accessoryKey}`,
                title: 'Accessory Name',
                defaultValue: accessory.name,
                error: 'Please Enter the Accessory Name'
              },
              (
                <Input
                  type='text'
                  placeholder='Please enter the address'
                />
              )
            )
          }
          {
            getFormFieldsDecorator(
              {
                name: `sum_insured${accessory.accessoryKey}`,
                title: 'Accessory Price',
                defaultValue: accessory.sum_insured,
                error: 'Please Enter the Accessory Price'
              },
              (
                <InputNumberStyle
                  type='number'
                  placeholder='Please enter the Accessory Price'
                />
              )
            )
          }
        </Col>
      </Row>
    )
  }, [form, getFormFieldsDecorator, handleUploadFile, handleRemoveAccessory])

  const handleAddNew = useCallback(() => {
    setNewAccessories(prevAccessories => {
      const accessories = [...prevAccessories, {
        accessoryKey: accessoryKey.current + 1
      }]
      accessoryKey.current += 1
      return accessories
    })
  }, [])

  return (
    <Modal
      visible={show}
      onCancel={onClose}
      onOk={handleFormSubmit}
      title='Add Accessory'
    >
      <Form noValidate>
        <AddonModalStyle>
          {
            newAccessories.map((accessory, index) => (
              renderAccessoryFormItem(accessory, index)
            ))
          }
          {
            isAddNew && (
              <Row type='flex' align='middle' justify='center'>
                <Col>
                  <Button type='primary' onClick={handleAddNew}>Add More</Button>
                </Col>
              </Row>
            )
          }
        </AddonModalStyle>
      </Form>
    </Modal>
  )
}

export default Form.create()(EditAccessoryModal)
