import { useCallback, useMemo, useRef, useState } from 'react'
import { Checkbox, Row, Col, Select } from 'antd'
import { formatMoney } from '../../../../../../../helpers/utility'
import { AddonItemStyle } from './index.style'
import { ADDONS_THIRD_PARTY_AMOUNT_RANGE, DRIVER_PASS_DATA_CODE } from '../../../../OfflineQuotes/constants'
import QuantityAddRemove from '../../../QuantityAddRemove'

function AddonItem ({
  addon, selectedAddon = {}, onSelectAddon,
  onPremiumCalculation, hidePremium = false
}) {
  const that = useRef({})
  const [qty, setQty] = useState(selectedAddon.no_passenger || 1)

  const getPremium = useCallback((value) => {
    that.current.initialPremium = value ? (value * addon.percentage) : 0
    if (hidePremium) {
      that.current.initialPremium = value
    }
    return that.current.initialPremium
  }, [addon, hidePremium])

  const defaultData = useMemo(() => {
    const { show_drop_down: showPremiumDropDown, premium } = addon
    let defaultSelect = showPremiumDropDown ? 15000000 : 0
    let addedPremium = selectedAddon.premium || premium
    if (DRIVER_PASS_DATA_CODE.includes(addon.add_on_code)) {
      // data = ADDONS_PASSENGER_LIMIT
      defaultSelect = 25000000
    }
    that.current.isQtyAddon = addon.add_on_code === 'passenger-insurance'
    if (!premium && addedPremium) {
      // there must be selected value for this case from select
      defaultSelect = selectedAddon.limit || defaultSelect
    } else if (!premium && showPremiumDropDown) {
      addedPremium = getPremium(defaultSelect)
    }
    return {
      defaultSelect,
      addedPremium
    }
  }, [addon, selectedAddon, getPremium])

  const handleOnCheckbox = useCallback((e, addon) => {
    if (e.target.checked) {
      let defaultSelect = 15000000
      if (DRIVER_PASS_DATA_CODE.includes(addon.add_on_code)) {
        defaultSelect = 25000000
      }
      if (!addon.show_drop_down) {
        defaultSelect = 0
      }
      let premium = 0
      if (addon.premium) {
        premium = addon.premium
      } else if (addon.calc_method !== 'p_calc') {
        premium = getPremium(defaultSelect)
      }
      onSelectAddon({
        ...addon,
        premium,
        limit: defaultSelect
      }, 'add')
      if (addon.calc_method === 'p_calc') {
        onPremiumCalculation({
          ...addon,
          value: defaultSelect
        })
      }
    } else {
      setQty(1)
      onSelectAddon({
        ...addon
      }, 'remove')
    }
  }, [onPremiumCalculation, onSelectAddon, getPremium])

  const handleOnSelect = useCallback((value, addon) => {
    let premium = 0
    if (addon.calc_method === 'p_calc') {
      onPremiumCalculation({
        ...addon,
        value
      })
    } else {
      premium = getPremium(value)
    }
    onSelectAddon({
      ...addon,
      limit: value,
      premium
    }, 'add')
  }, [onSelectAddon, onPremiumCalculation, getPremium])

  const handleQty = useCallback((qty) => {
    if (selectedAddon.add_on_code) {
      const oldPassenger = (selectedAddon.no_passenger || 1)
      setQty(qty)
      onSelectAddon({
        ...selectedAddon,
        premium: ((selectedAddon.premium * qty) / oldPassenger),
        no_passenger: qty
      }, 'add')
    }
  }, [setQty, selectedAddon, onSelectAddon])

  return (
    <AddonItemStyle>
      <Checkbox
        key={addon.add_on_code}
        value={addon.add_on_code}
        className='checkbox-label'
        onChange={(e) => handleOnCheckbox(e, addon)}
      >
        <span>{addon.add_on_name}</span><br />
        <span className='addon-premium'>{formatMoney(defaultData.addedPremium, 0, 'Mulai dari Rp ')}</span>
      </Checkbox>
      {
        addon.show_drop_down && (
          <Row
            className='addons-limit-select'
            type='flex'
            align='middle'
            justify='space-between'
          >
            <Col xl={15}>
              <Select
                onChange={(value) => handleOnSelect(value, addon)}
                value={selectedAddon.limit}
                className='addons-select'
              >
                {
                  ADDONS_THIRD_PARTY_AMOUNT_RANGE.map((limit) => (
                    <Select.Option
                      value={limit.value}
                      key={`${addon.add_on_code}_${limit.value}`}
                    >
                      {limit.display}
                    </Select.Option>
                  ))
                }
              </Select>
            </Col>
            {
              addon.add_on_code === 'passenger-insurance' && (
                <Col xl={5}>
                  <QuantityAddRemove
                    min={1}
                    max={7}
                    onUpdateQty={handleQty}
                    quantity={selectedAddon.no_passenger || qty}
                    className='quantity-add'
                  />
                </Col>
              )
            }
          </Row>
        )
      }
    </AddonItemStyle>
  )
}

export default AddonItem
