import { useState, useCallback, useMemo, useEffect } from 'react'
import { Col, Row, Icon, Table } from 'antd'
import { AddonsStyle } from './index.style'
import AddonsModal from './component/AddonsModal'
import { formatMoney } from '../../../../../helpers/utility'
import { getMappedDefaultAddons } from '../../helpers/utility'

function Addons ({ title = 'Addons Details', defaultAddons, onSaveAddonsData, isHideEditAction, policy }) {
  const [addonsModal, setAddonsModal] = useState(false)
  const [addons, setAddons] = useState([
    ...getMappedDefaultAddons(defaultAddons)
  ])

  useEffect(() => {
    onSaveAddonsData(defaultAddons)
  }, [onSaveAddonsData, defaultAddons])

  const addonColumns = useMemo(() => {
    return [
      {
        title: 'Addon Name',
        dataIndex: 'add_on_name'
      },
      {
        title: 'Addon Premium',
        dataIndex: 'premium',
        render: (value, props) => formatMoney(value, 0)
      }
    ]
  }, [])

  const handleAddons = useCallback(() => {
    setAddonsModal(true)
  }, [])

  const handleCloseAddons = useCallback(() => {
    setAddonsModal(false)
  }, [])

  const handleSaveAddons = useCallback((data) => {
    setAddonsModal(false)
    setAddons(data)
    onSaveAddonsData(data)
  }, [onSaveAddonsData])

  return (
    <AddonsStyle>
      <Row type='flex' justify='space-between' align='center'>
        <Col>
          <h3 className='policy-title'>{title || 'Addons Details'}</h3>
        </Col>
        {
          !isHideEditAction && (
            <Col>
              <Icon type='edit' onClick={handleAddons} />
            </Col>
          )
        }
      </Row>
      <Table
        pagination={{
          pageSize: 100
        }}
        columns={addonColumns}
        dataSource={addons}
        bordered
      />
      {
        addonsModal && (
          <AddonsModal
            show={addonsModal}
            onClose={handleCloseAddons}
            defaultAddons={addons}
            policy={policy}
            productCode='car-protection'
            onSave={handleSaveAddons}
          />
        )
      }
    </AddonsStyle>
  )
}

export default Addons
