export const getMappedDefaultAddons = (addons = []) => {
  return addons.map((addon) => ({
    add_on_name: addon.name,
    add_on_code: addon.code,
    limit: addon.sum_insured,
    premium: addon.premium,
    category_code: addon.category_code,
    no_passenger: addon.add_on_count
  }))
}

export function debounce(func, delay = 500) {
  let timeoutId;
  return function (...args) {
    // Clear any existing timer to reset the 500ms countdown
    clearTimeout(timeoutId);
    // Set a new timer to execute the function after 500ms
    timeoutId = setTimeout(() => {
      func.apply(this, args);
    }, delay);
  };
}