import { Upload, Icon } from 'antd'
import { UploadImgPreviewStyle } from './index.style'
import { useCallback, useEffect, useState } from 'react'
import { useGetFileUploadUrl } from '../../store/state/hooks/useAgentUtility'
import CircularLoader from '../../../../../components/CircularLoader'
import getUrlExtension from '../../../../../helpers/getExtensionUrl'

function UploadImgPreview ({ img, name, isNew, onSave, onRemove, fileType, disabled = false, isFileUploading }) {
  const [editImg, setEditImg] = useState(img)

  const getUploadImgPreviewPath = useCallback((fileUrl, data) => {
    setEditImg(fileUrl)
    onSave(fileUrl, data.type)
  }, [onSave])

  const { customRequest, UPLOAD_FILE_LOADER } = useGetFileUploadUrl(getUploadImgPreviewPath)

  const handleRemoveImg = useCallback((e) => {
    e.stopPropagation()
    onRemove()
  }, [onRemove])

  useEffect(() => {
    if (isFileUploading) {
      isFileUploading(UPLOAD_FILE_LOADER)
    }
  }, [UPLOAD_FILE_LOADER, isFileUploading])

  return (
    <Upload
      name={name || 'file'}
      id={name}
      multiple={false}
      showUploadList={false}
      accept={fileType || '.png,.jpg,.jpeg'}
      customRequest={(file) => { customRequest(file, name) }}
      value={editImg}
      data={editImg}
      disabled={disabled}
    >
      <CircularLoader isSpining={UPLOAD_FILE_LOADER}>
        <UploadImgPreviewStyle>
          {
            !isNew && onRemove && !disabled && (
              <div className='remove-img' onClick={handleRemoveImg}>
                <Icon type='close-circle' className='close-circle-icon' />
              </div>
            )
          }
          {
            isNew
              ? (
                <div className='text-center'>
                  <Icon type='upload' />
                  <div>Click to upload</div>
                </div>
                )
              : (getUrlExtension(editImg) === 'pdf')
                  ? (
                    <>
                      <div className='offline-pdf-upload-wrapper' />
                      <object
                        type='application/pdf'
                        data={editImg}
                        width='100%'
                        height='100%'
                        aria-label={name}
                      />
                    </>
                    )
                  : (
                    <img src={editImg} alt='' />
                    )
          }
          {!isNew && <span className='img-name'>{name}</span>}
        </UploadImgPreviewStyle>
      </CircularLoader>
    </Upload>
  )
}

export default UploadImgPreview
