import { useCallback, useEffect, useMemo, useState } from 'react'
import { AccessoryStyle, AccessoryActionStyle } from './index.style'
import ModalImage from 'react-modal-image'
import { Table, Icon, Row, Col, Modal } from 'antd'
import EditAccessoryModal from '../EditAccessoryModal'
import LayoutContentStyle from '../../../../../components/utility/layoutContent.style'

function Accessories ({ defaultAccessories, onSaveAccessory, isEdit, isDelete, notCalledStoreEffect }) {
  const [accessories, setAccessories] = useState(defaultAccessories)
  const [showAccessory, setShowAccessory] = useState({
    show: false,
    accessory: {}
  })

  useEffect(() => {
    if (defaultAccessories && !notCalledStoreEffect) {
      onSaveAccessory({
        accessories: defaultAccessories
      })
    }
  }, [defaultAccessories, onSaveAccessory, notCalledStoreEffect])

  const handleDeleteAccessory = useCallback((index) => {
    setAccessories(oldAccessories => {
      oldAccessories.splice(index, 1)
      onSaveAccessory({
        accessories: oldAccessories
      })
      return [...oldAccessories]
    })
  }, [onSaveAccessory])

  const handleDeleteConfirmation = useCallback((index) => {
    Modal.confirm({
      content: 'Are you sure, you want to delete this accessory?',
      okText: 'Yes',
      cancelText: 'No',
      onOk: () => handleDeleteAccessory(index)
    })
  }, [handleDeleteAccessory])

  const handleEditAccessory = useCallback((value, index) => {
    setShowAccessory({
      show: true,
      accessory: value,
      index: `${index}`
    })
  }, [])

  const handleCloseAccessoryEdit = useCallback((value) => {
    setShowAccessory({
      show: false,
      accessory: {}
    })
  }, [])

  const handleSaveAccessory = useCallback((data, editIndex) => {
    let newAccessories = [...accessories]
    if (editIndex) {
      newAccessories[parseInt(editIndex)] = data[0]
    } else {
      newAccessories = [...accessories, ...data]
    }
    setAccessories(newAccessories)
    onSaveAccessory({
      accessories: newAccessories
    })
    handleCloseAccessoryEdit()
  }, [
    onSaveAccessory, handleCloseAccessoryEdit, accessories
  ])

  const accessoryColumns = useMemo(() => {
    return ([
      {
        title: 'Photo',
        dataIndex: 'img',
        width: 300,
        render: (val) => (
          <AccessoryStyle>
            {
              val ? (<ModalImage className='object-image' small={val} large={val} />) : 'NA'
            }
          </AccessoryStyle>
        )
      },
      {
        title: 'Accessories Name',
        dataIndex: 'name'
      },
      {
        title: 'Accessories Type',
        dataIndex: 'accessory_type'
      },
      {
        title: 'Pricing',
        dataIndex: 'sum_insured'
      },
      {
        title: 'Action',
        align: 'center',
        render: (val, prop, index) => (
          <AccessoryActionStyle>
            <Icon type='edit' onClick={() => handleEditAccessory(val, index)} />
            {
              isDelete && <Icon type='delete' onClick={() => handleDeleteConfirmation(index)} />
            }
          </AccessoryActionStyle>
        )
      }]
    )
  }, [handleEditAccessory, isDelete, handleDeleteConfirmation])

  const handleAddNew = useCallback(() => {
    setShowAccessory({
      show: true,
      accessory: {},
      isNewAccessory: true
    })
  }, [])

  return (
    <LayoutContentStyle marginBtm='20px' borderRadius='8px'>
      <Row type='flex' justify='space-between' align='center'>
        <Col>
          <h3 className='policy-title'>Additional Accessories</h3>
        </Col>
        {
          isEdit && (
            <Col>
              <Icon type='edit' onClick={handleAddNew} />
            </Col>
          )
        }
      </Row>
      <Table
        pagination={{
          pageSize: 100
        }}
        columns={accessoryColumns}
        dataSource={accessories}
        bordered
      />
      {
        showAccessory.show && (
          <EditAccessoryModal
            show={showAccessory.show}
            accessory={showAccessory.accessory}
            onSave={handleSaveAccessory}
            onClose={handleCloseAccessoryEdit}
            editIndex={showAccessory.index}
            isAddNew={showAccessory.isNewAccessory}
          />
        )
      }
    </LayoutContentStyle>
  )
}

export default Accessories
