import moment from 'moment'
import { Col, message, Row } from 'antd'
import { useCallback, useEffect, useState } from 'react'
import { PolicyFormStyle } from './index.style'
import renderFormItemsUtil from '../../../../../../../../helpers/renderFormItems'
import { useUpdatePolicyFormRunTime, useValidatePostalCode } from '../../../../state/hooks/useAgentPolicyState'
import { PATH_FOR_AGENT_FILE_UPLOAD } from '../../../../../constants'
import { useUploadFile } from '../../../../../store/state/hooks/useAgentStore'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { findIndex } from 'lodash'
import CircularLoader from '../../../../../../../../components/CircularLoader'

function PolicyForm ({
  title, customerInfoForm, form, policyId,
  showReview, colSpan, onChange = () => {}
}) {
  const [{ runtimeUpdateFormData }, runtimeUpdatePolicyFormReq] = useUpdatePolicyFormRunTime()
  const [policyForm, setPolicyForm] = useState([...customerInfoForm])
  const [, uploadFileReq] = useUploadFile()
  const [{ validatePostalCodeData }, validatePostalCodeReq] = useValidatePostalCode()
  const [errorState] = useErrorContextValue()
  const [{ RUNTIME_UPDATE_FORM_LOADER, VALIDATE_POSTAL_CODE_LOADER }] = useLoaderContextValue()
  const { resetError } = useResetError()

  useEffect(() => {
    const { runtimeUpdateFormStatus, validatePostalCodeStatus } = errorState
    if (runtimeUpdateFormStatus === 'success') {
      const {
        target_key: targetKey, target_value: targetValue,
        target_attribute: targetAttribute
      } = runtimeUpdateFormData
      const indexOfItem = findIndex(customerInfoForm, { data_key: targetKey })
      if (targetAttribute === 'data') {
        form.setFieldsValue({
          [targetKey]: ''
        })
      }
      if (indexOfItem) {
        setPolicyForm(policyForm => {
          policyForm[indexOfItem] = {
            ...policyForm[indexOfItem],
            [targetAttribute]: targetValue
          }
          return [
            ...policyForm
          ]
        })
      }
      resetError(['runtimeUpdateFormStatus'])
    }

    if (validatePostalCodeStatus === 'success') {
      if (!validatePostalCodeData.success) {
        form.setFields({
          postal_code: {
            errors: [new Error('Postal code is invalid!')]
          }
        })
      }
      resetError(['validatePostalCodeStatus'])
    }
  }, [
    errorState, runtimeUpdateFormData, customerInfoForm,
    resetError, form, validatePostalCodeData
  ])

  const handleRuntimeParams = useCallback(({ name, value, runtimeRequestParams, handler = '' }) => {
    if (!value || !value.trim()) {
      return
    }
    const data = {}
    let isFieldEmpty = false

    runtimeRequestParams.forEach(key => {
      let val = form.getFieldValue(key)
      if ((key !== name) && (!val || !val.trim())) {
        isFieldEmpty = true
      } else {
        if (!isNaN(val)) {
          val = Number(parseFloat(val))
        }
        data[key] = val
      }
    })

    if (isFieldEmpty) {
      return
    }

    if (!isNaN(value)) {
      data[name] = Number(parseFloat(value))
    } else {
      data[name] = value
    }
    if (handler) {
      data.handler = handler
    } else {
      data.handler = name
    }

    runtimeUpdatePolicyFormReq({
      body: {
        ...data
      },
      policyId
    })
  }, [runtimeUpdatePolicyFormReq, policyId, form])

  const handleInputChange = useCallback((value, name) => {
    if (name === 'postal_code' && (`${value}`.length === 5)) {
      // handle postal code validations
      validatePostalCodeReq({
        body: {
          postal_code: value
        }
      })
    }
    return value
  }, [validatePostalCodeReq])

  const handleDisabledDate = useCallback((current, name) => {
    switch (name) {
      case 'request_date':
      case 'submission_date':
      case 'receive_date':
        return current > moment().endOf('day')
      default:
        break
    }
  }, [])

  const customRequest = useCallback(({ file }, name) => {
    // that.currentUploadType = name
    const formData = new FormData()
    // we are sending this values for storage identification
    // can we upload any type of file like png, jpg, pdf
    if (file.name) {
      const fileName = file.name.split('.')[0]
      formData.append('file', file)
      formData.append('path', `${PATH_FOR_AGENT_FILE_UPLOAD}/${fileName}_${Date.parse(new Date())}`)
      formData.append('identifier', 'agent')
      uploadFileReq({ body: formData })
    }
  }, [uploadFileReq])

  const keyDisabled = useCallback(() => {
    return false
  }, [])

  const beforeUpload = useCallback((file, name) => {
    // file size validation for 10MB
    const isLt10M = file.size / 1024 / 1024 <= 10
    if (!isLt10M) {
      message.error('file must smaller than 10MB!')
    }
    return isLt10M
  }, [])

  const handleChangeMultiFormData = useCallback((data, type) => {
    onChange(data, type)
  }, [onChange])

  const renderCustomerInfo = useCallback(() => {
    return (
      <Row type='flex' justify='space-between'>
        {
          policyForm.map((attribute, i) => {
            return (
              <Col span={colSpan || 11} key={i}>
                {
                  renderFormItemsUtil({
                    name: attribute.data_key,
                    title: attribute.title,
                    subTitle: attribute.sub_title,
                    fileData: attribute.file_data,
                    disabled: showReview || keyDisabled(attribute.data_key),
                    type: attribute.type,
                    defaultValue: attribute.default_value,
                    isEnableType: false,
                    runtimeRequestParams: attribute.runtime_request_params,
                    data: attribute.data,
                    dataType: attribute.data_type,
                    getFieldDecorator: form.getFieldDecorator,
                    getFieldValue: form.getFieldValue,
                    defaultRadioValue: attribute.default_radio_button,
                    handleRuntimeParams: handleRuntimeParams,
                    handleInputChange: handleInputChange,
                    handleDisabledDate: handleDisabledDate,
                    customRequest: customRequest,
                    isKeyDisabled: keyDisabled,
                    beforeUpload: beforeUpload,
                    handleChangeMultiFormData: handleChangeMultiFormData
                  })
                }
              </Col>
            )
          })
        }
      </Row>
    )
  }, [
    policyForm, form, colSpan, showReview,
    beforeUpload, keyDisabled, customRequest, handleChangeMultiFormData,
    handleInputChange, handleRuntimeParams, handleDisabledDate
  ])

  return (
    <PolicyFormStyle>
      <CircularLoader isSpining={RUNTIME_UPDATE_FORM_LOADER || VALIDATE_POSTAL_CODE_LOADER}>
        <h3 className='policy-title'>{title}</h3>
        {
          renderCustomerInfo()
        }
      </CircularLoader>
    </PolicyFormStyle>
  )
}

export default PolicyForm
