import { Form, Modal, Card, Checkbox } from 'antd'
import { useCallback, useEffect, useRef, useState } from 'react'
import CircularLoader from '../../../../../../../components/CircularLoader'
import { useGetAddons, useGetAddonsPremium, useUpdateAgentStore } from '../../../../store/state/hooks/useAgentStore'

import { AddonsModalStyle } from './index.style'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { getAddonsRequestBody } from '../../../../helpers/getAddonsReqBody'
import AddonItem from '../AddonItem'

function AddonsModal ({ policy, show, onClose, onSave, loader, form, defaultAddons = {} }) {
  const [preFilledAddons, setPreFilledAddons] = useState({})
  const [preFilledAddonItems, setPreFilledAddonItems] = useState({})
  const [{ getAddonsData }, getAddonsRequest] = useGetAddons()
  const [{ getAddonsPremiumData }, getAddonsPremiumReq] = useGetAddonsPremium()
  const [{ getAddonsStatus, getAddonsPremiumStatus }] = useErrorContextValue()
  const [{ GET_ADDONS_LOADER, GET_ADDONS_PREMIUM_LOADER }] = useLoaderContextValue()
  const { resetError } = useResetError()
  const updateAgentStore = useUpdateAgentStore()
  const selectedAddonRef = useRef()

  useEffect(() => {
    getAddonsRequest({
      productCode: policy.provider_package.code,
      body: {
        ...getAddonsRequestBody(policy)
      }
    })
  }, [getAddonsRequest, policy])

  const updateTheSelectedAddons = useCallback((selectedAddon) => {
    setPreFilledAddonItems(prevAddonsItems => {
      prevAddonsItems[selectedAddon.add_on_code] = {
        ...selectedAddon
      }
      return {
        ...prevAddonsItems
      }
    })
  }, [])

  const handleAddonPremium = useCallback((addon) => {
    getAddonsPremiumReq({
      body: {
        addon_code: addon.add_on_code,
        addon_count: 1,
        sum_insured: addon.value,
        code: policy?.provider_package?.package?.product.code,
        usage: policy.request.usage,
        variant_code: policy.request.variant_code,
        vehicle_type: policy.request.vehicle_type,
        year: policy.request.year,
        package_type: policy.request.package_type
      },
      productCode: policy?.provider_package?.package?.product.code
    })
  }, [policy, getAddonsPremiumReq])

  useEffect(() => {
    if (getAddonsStatus === 'success') {
      const addonData = {}
      defaultAddons.forEach(addon => {
        addonData[addon.category_code] = {
          ...addonData[addon.category_code],
          [addon.add_on_code]: addon
        }
      })
      const addonsMap = {}
      let addonItemsMap = {}
      getAddonsData.forEach(addonCat => {
        const addon = addonData[addonCat.category_code]
        if (addon) {
          addonsMap[addonCat.category_code] = Object.keys(addon)
          addonItemsMap = {
            ...addonItemsMap,
            ...addon
          }
        }
      })
      setPreFilledAddons({ ...addonsMap })
      setPreFilledAddonItems(addonItemsMap)
      resetError(['getAddonsStatus'])
    }

    if (getAddonsPremiumStatus === 'success' && getAddonsPremiumData && selectedAddonRef.current) {
      selectedAddonRef.current.premium = getAddonsPremiumData.premium
      updateTheSelectedAddons(selectedAddonRef.current)
      selectedAddonRef.current = undefined
      resetError(['getAddonsPremiumStatus'])
      updateAgentStore({
        getAddonsPremiumData: undefined
      })
    }
  }, [
    getAddonsStatus, resetError, defaultAddons.addons, getAddonsData,
    getAddonsPremiumStatus, getAddonsPremiumData, updateAgentStore,
    defaultAddons, updateTheSelectedAddons
  ])

  const handleSave = useCallback(() => {
    onSave(Object.values(preFilledAddonItems))
  }, [onSave, preFilledAddonItems])

  const handleOnSelect = useCallback((selectedAddon, actionType) => {
    selectedAddonRef.current = selectedAddon
    if (actionType === 'add' && (selectedAddon.calc_method !== 'p_calc')) {
      updateTheSelectedAddons(selectedAddon)
      selectedAddonRef.current = undefined
    } else if (actionType === 'remove') {
      setPreFilledAddonItems(prevAddonsItems => {
        delete prevAddonsItems[selectedAddon.add_on_code]
        return {
          ...prevAddonsItems
        }
      })
    }
  }, [updateTheSelectedAddons])

  const renderCategoryAddons = useCallback((addons, categoryCode) => {
    const { getFieldDecorator } = form
    const mapCheckbox = addons.map((addon, index) => (
      <AddonItem
        key={addon.add_on_code}
        addon={addon}
        selectedAddon={preFilledAddonItems[addon.add_on_code] || {}}
        onSelectAddon={(selectedAddon, actionType) => handleOnSelect({ ...selectedAddon, category_code: categoryCode }, actionType)}
        onPremiumCalculation={handleAddonPremium}
      />
    ))
    return (
      <Form.Item>
        {
          getFieldDecorator(
            categoryCode,
            {
              initialValue: preFilledAddons[categoryCode] || []
            }
          )(
            <Checkbox.Group key={categoryCode} className='addon-checkbox-group'>
              {mapCheckbox}
            </Checkbox.Group>
          )
        }
      </Form.Item>
    )
  }, [
    form, preFilledAddons, preFilledAddonItems,
    handleOnSelect, handleAddonPremium
  ])

  const renderAddons = useCallback(() => {
    const addonsRender = []
    getAddonsData.forEach((addonCategory) => {
      const addonElement = (
        <Card
          title={addonCategory.category_name}
          bordered
          key={addonCategory.category_code}
          className='card-margin-btm'
        >
          {renderCategoryAddons(addonCategory.add_on, addonCategory.category_code)}
        </Card>
      )
      addonsRender.push(addonElement)
    })
    return addonsRender
  }, [
    getAddonsData, renderCategoryAddons
  ])

  return (
    <Modal
      visible={show}
      okText='Save'
      onCancel={onClose}
      onOk={handleSave}
      title='Edit Addons'
      okButtonProps={{
        loading: loader
      }}
    >
      <CircularLoader isSpining={GET_ADDONS_LOADER || GET_ADDONS_PREMIUM_LOADER || loader}>
        <AddonsModalStyle>
          <Form noValidate>
            {getAddonsData && renderAddons()}
          </Form>
        </AddonsModalStyle>
      </CircularLoader>
    </Modal>
  )
}

export default Form.create()(AddonsModal)
