export const getAddonsRequestBody = (policy) => {
  const request = policy.request || {}
  if (policy?.provider_package?.package?.product.code === 'car-protection') {
    return {
      purchase_type: request.purchase_type,
      package_type: request.package_type,
      vehicle_type: request.vehicle_type,
      brand: request.brand,
      variant: request.variant,
      variant_code: request.variant_code,
      additional_sum_insured: request.additional_sum_insured,
      year: request.year,
      model: request.model,
      region_code: request.region_code,
      vehicle_sum_insured: request.vehicle_sum_insured,
      vehicle_plate_no: request.vehicle_plate_no,
      usage: request.usage,
      start_date: request.start_date,
      accessories: request.accessories
    }
  }

  return {
    occupation_code: request.occupation_code,
    province_code: request.province_code,
    sum_insured: request.sum_insured,
    zone: request.zone
  }
}
